int sum_array(int *arr, int size) {
    int total = 0;
    for (int i = 0; i < size; i++) {
        total += arr[i];
    }
    return total;
}

// Example usage and demonstration of style
#include <stdio.h>

void print_sum_result(int *array, int array_size, int expected_sum) {
    int actual_sum = sum_array(array, array_size);
    if (actual_sum == expected_sum) {
        printf("Test passed: Sum is %d\n", actual_sum);
    } else {
        printf("Test failed: Expected %d, got %d\n", expected_sum, actual_sum);
    }
}

int main() {
    int arr1[] = {1, 2, 3};
    print_sum_result(arr1, 3, 6);

    int arr2[] = {-1, 0, 10};
    print_sum_result(arr2, 3, 9);

    int arr3[] = {};
    if (sum_array(arr3, 0) == 0) {
        printf("Test passed: Empty array sum is 0\n");
    } else {
        printf("Test failed: Empty array sum not 0\n");
