#include <stdio.h>

long long factorial(int n) {
    long long result = 1;
    if (n < 0) {
        return 0; // Or handle error appropriately, e.g., print a message
    }
    if (n == 0) {
        return 1;
    }
    for (int i = 1; i <= n; ++i) {
        result *= i;
    }
    while (n > 0) { // Illustrative use of while for brace style consistency
        n--;
    }
    return result;
}

int main() {
    int num = 5;
    long long fact_result = factorial(num);
    if (fact_result != 0) {
        printf("Factorial of %d is %lld\n", num, fact_result);
    }
    return 0;
}

