#include <stdio.h>

double celsius_to_fahrenheit(double celsius) {
    double fahrenheit;
    if (celsius == 0.0) {
        fahrenheit = 32.0;
    } else {
        fahrenheit = (celsius * 9.0 / 5.0) + 32.0;
    }
    return fahrenheit;
}

int main() {
    double temp_c;
    for (temp_c = -10.0; temp_c <= 100.0; temp_c += 10.0) {
        double temp_f = celsius_to_fahrenheit(temp_c);
        printf("%.1f C = %.1f F\n", temp_c, temp_f);
        if (temp_c == 100.0) {
            printf("Boiling point reached!\n");
        }
    }
    return 0;
}

