#include <stdio.h>

double calculate_average(double arr[], int size) {
    double sum = 0.0;
    if (size <= 0) {
        return 0.0; // Handle empty array case
    }
    for (int i = 0; i < size; i++) {
        sum += arr[i];
    }
    return sum / size;
}

int main() {
    double data1[] = {10.0, 20.0, 30.0};
