#include <stdio.h>

int find_substring(const char *haystack, const char *needle) {
    int i = 0;
    while (haystack[i] != '\0') {
        int j = 0;
        int match = 1;
        while (needle[j] != '\0') {
            if (haystack[i + j] == '\0' || haystack[i + j] != needle[j]) {
                match = 0;
                break;
            }
            j++;
        }
        if (match) {
            return 1;
        }
        i++;
    }
    return 0;
}

int main() {
    if (find_substring("hello world", "world")) {
        printf("Found 'world' in 'hello world'\n");
    }
    if (!find_substring("abc", "xyz")) {
        printf("Did not find 'xyz' in 'abc'\n");
    }
    return 0;
}

