#include <stdio.h>

void print_row(int spaces, int stars) {
    for (int i = 0; i < spaces; i++) {
        printf(" ");
    }
    for (int i = 0; i < stars; i++) {
        printf("*");
    }
    printf("\n");
}

void print_upper_half(int max_width) {
    for (int current_width = 1; current_width <= max_width; current_width += 2) {
        int spaces = (max_width - current_width) / 2;
        print_row(spaces, current_width);
    }
}

void print_lower_half(int max_width) {
    for (int current_width = max_width - 2; current_width >= 1; current_width -= 2) {
        int spaces = (max_width - current_width) / 2;
        print_row(spaces, current_width);
    }
}

void print_diamond(int max_width) {
    if (max_width % 2 == 0) {
        printf("Error: Maximum width must be an odd number.\n");
        return;
    }

    print_upper_half(max_width);
    print_lower_half(max_width);
}

int main() {
    print_diamond(3);
    printf("\n");
    print_diamond(5);
    printf("\n");
    print_diamond(7);
    return 0;
}

