#include <stdio.h>

int enqueue(int queue[], int* head, int* tail, int size, int val) {
    if ((*tail + 1) % size == *head) {
        return -1; // Queue is full
    }
    queue[*tail] = val;
    *tail = (*tail + 1) % size;
    return 0;
}

int dequeue(int queue[], int* head, int* tail, int size) {
    if (*head == *tail) {
        return -1; // Queue is empty
    }
    int val = queue[*head];
    *head = (*head + 1) % size;
    return val;
}

int main() {
    int queue[3];
    int head = 0;
    int tail = 0;
    int size = 3;

    if (enqueue(queue, &head, &tail, size, 10) == 0) {
        printf("Enqueued: 10\n");
    }
    if (enqueue(queue, &head, &tail, size, 20) == 0) {
        printf("Enqueued: 20\n");
    }

    int val = dequeue(queue, &head, &tail, size);
    if (val != -1) {
        printf("Dequeued: %d\n", val); // Expect 10
    }
    val = dequeue(queue, &head, &tail, size);
    if (val != -1) {
        printf("Dequeued: %d\n", val); // Expect 20
    }
    val = dequeue(queue, &head, &tail, size);
    if (val == -1) {
        printf("Queue is empty (as expected)\n");
    }

    return 0;
}

