#include <stdlib.h>
#include <string.h>

#define INITIAL_BUFFER_SIZE 128

char* read_first_line(const char* filename) {
    FILE* file = fopen(filename, "r");
    if (file == NULL) {
        return NULL;
    }

    char* line = NULL;
    size_t len = 0;
    ssize_t read;

    // The POSIX getline function is convenient for this task.
    // However, since it's not standard C, we'll implement a compatible version
    // or use a fixed-size buffer approach if getline is unavailable.
    // For this exercise, let's assume a standard C approach without POSIX extensions.

    int buffer_size = INITIAL_BUFFER_SIZE;
    line = (char*)malloc(buffer_size);
    if (line == NULL) {
        fclose(file);
        return NULL;
    }
    line[0] = '\0'; // Initialize to empty string

    int i = 0;
    int c;
    while ((c = fgetc(file)) != EOF && c != '\n') {
        if (i >= buffer_size - 1) { // -1 for null terminator
            buffer_size *= 2;
            char* new_line = (char*)realloc(line, buffer_size);
            if (new_line == NULL) {
                free(line);
                fclose(file);
                return NULL;
            }
            line = new_line;
        }
        line[i++] = (char)c;
    }
    line[i] = '\0';

    fclose(file);
    return line;
}

