#include <stdio.h>

void swap_array_elements(int arr[], int index1, int index2, int size) {
    if (index1 >= 0 && index1 < size && index2 >= 0 && index2 < size) {
        if (index1 != index2) {
            int temp = arr[index1];
            arr[index1] = arr[index2];
            arr[index2] = temp;
        }
    }
}

void print_array(int arr[], int size) {
    for (int i = 0; i < size; i++) {
        printf("%d ", arr[i]);
    }
    printf("\n");
}

int main() {
    int arr1[] = {10, 20, 30};
    int size1 = sizeof(arr1) / sizeof(arr1[0]);
    swap_array_elements(arr1, 0, 2, size1);
    print_array(arr1, size1);

    int arr2[] = {10, 20};
    int size2 = sizeof(arr2) / sizeof(arr2[0]);
    swap_array_elements(arr2, 0, 0, size2);
    print_array(arr2, size2);

    int arr3[] = {5, 15, 25, 35};
    int size3 = sizeof(arr3) / sizeof(arr3[0]);
    int x = 1;
    while (x < size3 - 1) {
        swap_array_elements(arr3, x, x + 1, size3);
        x++;
    }
    print_array(arr3, size3);

    return 0;
}

