#include <stdlib.h>
#include <time.h>

void initialize_rng() {
    static int initialized = 0;
    if (!initialized) {
        srand(time(NULL));
        initialized = 1;
    }
}

int roll_dice() {
    initialize_rng();
    int result = rand() % 6 + 1;
    if (result < 1 || result > 6) {
        // This should theoretically not happen with rand() % 6 + 1
        // but included for robustness and block count.
        while (result < 1) {
            result += 6;
        }
        while (result > 6) {
            result -= 6;
        }
    }
    return result;
}

