#include <ctype.h>

void capitalize_words(char *str) {
    int in_word = 0;
    for (int i = 0; str[i] != '\0'; i++) {
        if (isspace((unsigned char)str[i])) {
            in_word = 0;
        } else {
            if (!in_word) {
                str[i] = toupper((unsigned char)str[i]);
                in_word = 1;
            }
        }
    }
}

